// Detect what the user sent: a URL, a file (sitemap.xml or urllist), or nothing usable.
const message = $input.first().json.message;
const text = message.text || message.caption || '';
const chatId = message.chat.id;

const doc = message.document;
const hasFile = !!doc;

let mode = 'unknown';
let fileId = null;
let fileName = null;

if (hasFile) {
  fileId = doc.file_id;
  fileName = doc.file_name || 'unknown';
  const ext = fileName.split('.').pop().toLowerCase();

  if (ext === 'xml' || fileName.toLowerCase().includes('sitemap')) {
    mode = 'sitemap';
  } else if (['txt', 'md', 'csv'].includes(ext)) {
    mode = 'urllist';
  } else {
    mode = 'unsupported_file';
  }
} else {
  const urlRegex = /(https?:\/\/[^\s]+)/gi;
  const matches = text.match(urlRegex);
  mode = (matches && matches.length > 0) ? 'single' : 'no_url';
}

let url = null;
if (mode === 'single') {
  const urlRegex = /(https?:\/\/[^\s]+)/gi;
  const matches = text.match(urlRegex);
  url = matches[0].replace(/[.,;:!?)]+$/, '');
}

return {
  json: { mode, chatId, text, url, fileId, fileName }
};

