// Parse URLs out of a sitemap.xml or text-with-URLs file.
// Detects sitemap-index files (rejects them) so we don't try to scrape XML as HTML.
const content = $input.first().json.data;
const detect = $('Detect Input Mode').first().json;
const mode = detect.mode;
const chatId = detect.chatId;
const fileName = detect.fileName;

let urls = [];
let warning = null;

if (mode === 'sitemap') {
  // Reject sitemap index (contains <sitemap>...<loc>nested.xml</loc>...</sitemap>)
  if (/<sitemapindex\b/i.test(content)) {
    return {
      json: {
        chatId,
        fileName,
        totalUrls: 0,
        urls: [],
        error: 'sitemap_index',
        message: 'This is a sitemap index file. Send the individual child sitemap files instead.'
      }
    };
  }
  const locRegex = /<loc>([^<]+)<\/loc>/gi;
  let m;
  while ((m = locRegex.exec(content)) !== null) {
    urls.push(m[1].trim());
  }
} else {
  const lines = content.split(/[\r\n]+/);
  for (const line of lines) {
    const t = line.trim();
    if (!t || t.startsWith('#')) continue;
    const um = t.match(/(https?:\/\/[^\s\)\]]+)/);
    if (um) urls.push(um[1].replace(/[.,;:!?)]+$/, ''));
  }
}

urls = [...new Set(urls)];

if (urls.length === 0 && !warning) {
  return {
    json: {
      chatId, fileName, totalUrls: 0, urls: [],
      error: 'empty', message: 'No URLs found in the file.'
    }
  };
}

return { json: { chatId, fileName, totalUrls: urls.length, urls } };

// Per-chat state isolation. staticData is workflow-global, so we key by chatId
// to prevent two concurrent batches (or two users) from colliding.
const data = $input.first().json;
const chatId = data.chatId;

const staticData = $getWorkflowStaticData('global');
staticData.runs = staticData.runs || {};

// Always overwrite this chat's slot - any prior run for this chat is stale by definition
staticData.runs[chatId] = {
  processed: 0,
  succeeded: 0,
  failed: [],
  totalUrls: data.totalUrls,
  startTime: Date.now()
};

// Emit one item per URL for SplitInBatches to consume
return data.urls.map((url, i) => ({
  json: {
    url,
    index: i + 1,
    totalUrls: data.totalUrls,
    chatId
  }
}));

// Increment per-chat counters and decide whether to emit a progress update.
const item = $('Process One at a Time').first().json;
const chatId = item.chatId;

const staticData = $getWorkflowStaticData('global');
staticData.runs = staticData.runs || {};
const run = staticData.runs[chatId];

// If state was cleared (eg. cancelled/restarted), pass through without crashing.
if (!run) {
  return { json: { chatId, processed: 0, succeeded: 0, failed: [], totalUrls: 0,
                   shouldSendUpdate: false, elapsedTime: '' } };
}

run.processed++;
run.succeeded++;

const total = run.totalUrls;
// Aim for ~5 progress messages across the run, capped at every 10 items, min every 1.
const interval = Math.max(1, Math.min(10, Math.floor(total / 5)));
const shouldSendUpdate = run.processed % interval === 0 && run.processed < total;

const elapsed = Math.floor((Date.now() - run.startTime) / 1000);
const mins = Math.floor(elapsed / 60);
const secs = elapsed % 60;
const elapsedTime = mins > 0 ? `${mins}m ${secs}s` : `${secs}s`;

return {
  json: {
    chatId,
    processed: run.processed,
    succeeded: run.succeeded,
    failed: run.failed,
    totalUrls: total,
    shouldSendUpdate,
    elapsedTime
  }
};

// Increment per-chat counters and decide whether to emit a progress update.
const item = $('Process One at a Time').first().json;
const chatId = item.chatId;

const staticData = $getWorkflowStaticData('global');
staticData.runs = staticData.runs || {};
const run = staticData.runs[chatId];

// If state was cleared (eg. cancelled/restarted), pass through without crashing.
if (!run) {
  return { json: { chatId, processed: 0, succeeded: 0, failed: [], totalUrls: 0,
                   shouldSendUpdate: false, elapsedTime: '' } };
}

run.processed++;
run.failed.push(item.url);

const total = run.totalUrls;
// Aim for ~5 progress messages across the run, capped at every 10 items, min every 1.
const interval = Math.max(1, Math.min(10, Math.floor(total / 5)));
const shouldSendUpdate = run.processed % interval === 0 && run.processed < total;

const elapsed = Math.floor((Date.now() - run.startTime) / 1000);
const mins = Math.floor(elapsed / 60);
const secs = elapsed % 60;
const elapsedTime = mins > 0 ? `${mins}m ${secs}s` : `${secs}s`;

return {
  json: {
    chatId,
    processed: run.processed,
    succeeded: run.succeeded,
    failed: run.failed,
    totalUrls: total,
    shouldSendUpdate,
    elapsedTime
  }
};

// SplitInBatches output 0 ("done") emits the original items. Pull chatId from the first,
// then read final stats from per-chat state and build the completion message.
const first = $input.first().json;
const chatId = first.chatId;

const staticData = $getWorkflowStaticData('global');
const run = staticData.runs?.[chatId];

if (!run) {
  return { json: { chatId, processed: 0, succeeded: 0, totalUrls: 0,
                   elapsedTime: '0s', failedSection: '', failed: [] } };
}

const elapsed = Math.floor((Date.now() - run.startTime) / 1000);
const mins = Math.floor(elapsed / 60);
const secs = elapsed % 60;
const elapsedTime = mins > 0 ? `${mins}m ${secs}s` : `${secs}s`;

// Truncate failed URL list by char budget, not item count (Telegram limit = 4096).
const BUDGET = 3000;
let failedSection = '';
if (run.failed.length > 0) {
  const lines = [];
  let chars = 0, shown = 0;
  for (const u of run.failed) {
    if (chars + u.length + 1 > BUDGET) break;
    lines.push(u);
    chars += u.length + 1;
    shown++;
  }
  const remaining = run.failed.length - shown;
  failedSection = `\n❌ Failed: ${run.failed.length}\n\nFailed URLs:\n${lines.join('\n')}` +
    (remaining > 0 ? `\n... and ${remaining} more` : '');
}

return {
  json: {
    chatId,
    processed: run.processed,
    succeeded: run.succeeded,
    failed: run.failed,
    totalUrls: run.totalUrls,
    elapsedTime,
    failedSection
  }
};

// Per-chat cleanup - leave other concurrent runs alone.
const chatId = $input.first().json.chatId;
const staticData = $getWorkflowStaticData('global');
if (staticData.runs && staticData.runs[chatId]) {
  delete staticData.runs[chatId];
}
return { json: { chatId, cleared: true } };

// Strip HTML to readable markdown for downstream use.
// Not a full converter - good enough for text extraction.
const html = $json.data || '';
const sourceUrl = $('Detect Input Mode').first().json.url;
const chatId = $('Detect Input Mode').first().json.chatId;

function htmlToMarkdown(input) {
  let s = input;

  // Remove non-content blocks entirely
  s = s.replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, '');
  s = s.replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, '');
  s = s.replace(/<noscript\b[^>]*>[\s\S]*?<\/noscript>/gi, '');
  s = s.replace(/<svg\b[^>]*>[\s\S]*?<\/svg>/gi, '');
  s = s.replace(/<!--[\s\S]*?-->/g, '');

  // Capture title for the doc header before stripping
  const titleMatch = s.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  const title = titleMatch ? titleMatch[1].trim().replace(/\s+/g, ' ') : '';

  // Strip <head> contents (after grabbing title)
  s = s.replace(/<head\b[^>]*>[\s\S]*?<\/head>/gi, '');

  // Headings
  for (let lvl = 1; lvl <= 6; lvl++) {
    const re = new RegExp(`<h${lvl}\\b[^>]*>([\\s\\S]*?)</h${lvl}>`, 'gi');
    s = s.replace(re, (_, t) => '\n\n' + '#'.repeat(lvl) + ' ' + t.trim() + '\n\n');
  }

  // Links: [text](url)
  s = s.replace(/<a\b[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi,
                (_, href, t) => `[${t.trim()}](${href})`);

  // Emphasis
  s = s.replace(/<(strong|b)\b[^>]*>([\s\S]*?)<\/\1>/gi, '**$2**');
  s = s.replace(/<(em|i)\b[^>]*>([\s\S]*?)<\/\1>/gi, '*$2*');
  s = s.replace(/<code\b[^>]*>([\s\S]*?)<\/code>/gi, '`$1`');

  // Lists
  s = s.replace(/<li\b[^>]*>([\s\S]*?)<\/li>/gi, '- $1\n');

  // Paragraphs / breaks
  s = s.replace(/<\/p>/gi, '\n\n');
  s = s.replace(/<br\s*\/?>/gi, '\n');
  s = s.replace(/<\/div>/gi, '\n');

  // Strip remaining tags
  s = s.replace(/<[^>]+>/g, '');

  // Decode common entities
  const entities = {
    '&nbsp;': ' ', '&amp;': '&', '&lt;': '<', '&gt;': '>',
    '&quot;': '"', '&#39;': "'", '&apos;': "'", '&mdash;': '—',
    '&ndash;': '–', '&hellip;': '…', '&copy;': '©', '&reg;': '®'
  };
  for (const [e, ch] of Object.entries(entities)) {
    s = s.replace(new RegExp(e, 'g'), ch);
  }
  // Numeric entities
  s = s.replace(/&#(\d+);/g, (_, n) => String.fromCharCode(parseInt(n, 10)));

  // Collapse whitespace
  s = s.replace(/[ \t]+/g, ' ');
  s = s.replace(/\n[ \t]+/g, '\n');
  s = s.replace(/\n{3,}/g, '\n\n');

  return { markdown: s.trim(), title };
}

const { markdown, title } = htmlToMarkdown(html);

// Build the file: front-matter + content
const scrapedAt = new Date().toISOString();
const fileBody =
  `---\n` +
  `source: ${sourceUrl}\n` +
  `title: ${title}\n` +
  `scraped_at: ${scrapedAt}\n` +
  `---\n\n` +
  (title ? `# ${title}\n\n` : '') +
  markdown;

// Filename derived from URL (safe chars only)
function urlToFileName(u) {
  try {
    const url = new URL(u);
    const host = url.hostname.replace(/^www\./, '');
    let path = url.pathname.replace(/\/$/, '').replace(/\//g, '_') || '_root';
    return `${host}${path}.md`.replace(/[^a-zA-Z0-9._-]/g, '_').slice(0, 120);
  } catch {
    return `scrape_${Date.now()}.md`;
  }
}
const fileName = urlToFileName(sourceUrl);

// Emit json + binary so the Telegram sendDocument node can attach the file
return {
  json: { chatId, sourceUrl, fileName, charCount: markdown.length, title },
  binary: {
    data: {
      data: Buffer.from(fileBody, 'utf8').toString('base64'),
      mimeType: 'text/markdown',
      fileName,
      fileExtension: 'md'
    }
  }
};
